240→// Handle GET requests: ?shop=...&zip=...
241→export const loader = async ({ request }: LoaderFunctionArgs) => {
242→  const url = new URL(request.url);
243→
244→  // Handle CORS preflight
245→  if (request.method === "OPTIONS") {
246→    return new Response(null, { status: 204, headers: CORS_HEADERS });
247→  }
248→
249→  const shop = url.searchParams.get("shop");
250→  const zip = url.searchParams.get("zip");
251→  return handleZipCheck(shop, zip);
252→};
253→
254→// Handle POST requests with JSON body: { shop, zip }
255→export const action = async ({ request }: ActionFunctionArgs) => {
256→  let shop: string | null = null;
257→  let zip: string | null = null;
258→
259→  try {
260→    const body = await request.json();
261→    shop = body?.shop ?? null;
262→    zip = body?.zip ?? null;
263→  } catch {
264→    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
265→      status: 400,
266→      headers: CORS_HEADERS,
267→    });
268→  }
269→
270→  return handleZipCheck(shop, zip);
271→};
